// 编写日期：2026年8月5日
// 作者：zidong
// 程序说明：图书管理系统 - 管理员类

#ifndef ADMIN_HPP
#define ADMIN_HPP

#include <string>
#include <vector>
#include "book.hpp"

using std::string;
using std::vector;

// 管理员类：负责图书出入库管理工作
class Admin {
public:
    Admin() : username(""), password("") {}
    Admin(const string& name, const string& pwd)
        : username(name), password(pwd) {}

    // 获取用户名
    string getUsername() const { return username; }
    // 获取密码
    string getPassword() const { return password; }

    // 图书入库：新增图书，或对已存在的图书增加库存
    // 在 books 中查找编号为 bookId 的图书，找到则加库存，否则新增一本
    static void addBook(vector<Book>& books, const string& bookId,
                        const string& bookName, int count) {
        for (size_t i = 0; i < books.size(); ++i) {
            if (books[i].getId() == bookId) {
                books[i].inStock(count);   // 已存在，增加库存
                std::cout << "入库成功：\"" << bookName << "\" 库存增加 "
                          << count << " 本，当前库存 "
                          << books[i].getStock() << " 本。" << std::endl;
                return;
            }
        }
        books.push_back(Book(bookId, bookName, count));   // 不存在，新增图书
        std::cout << "入库成功：新增图书 \"" << bookName
                  << "\" 共 " << count << " 本。" << std::endl;
    }

    // 图书出库：减少库存，若库存不足或不存在返回 false
    static bool removeBook(vector<Book>& books, const string& bookId, int count) {
        if (count < 0) return false;
        for (size_t i = 0; i < books.size(); ++i) {
            if (books[i].getId() == bookId) {
                if (books[i].outStock(count)) {
                    std::cout << "出库成功：\"" << books[i].getName()
                              << "\" 出库 " << count << " 本，剩余库存 "
                              << books[i].getStock() << " 本。" << std::endl;
                    return true;
                } else {
                    std::cout << "出库失败：库存不足，当前库存仅 "
                              << books[i].getStock() << " 本。" << std::endl;
                    return false;
                }
            }
        }
        std::cout << "出库失败：未找到编号为 " << bookId << " 的图书。" << std::endl;
        return false;
    }

private:
    string username; // 管理员用户名
    string password; // 管理员密码
};

#endif // ADMIN_HPP
